        if dx != 0 or dy != 0:
            return [dx, dy]

    # Fallback: move toward center of grid if known
    if grid_w and grid_h:
        cx, cy = grid_w // 2, grid_h // 2
        dx = 1 if cx > sx else -1 if cx < sx else 0
        dy = 1 if cy > sy else -1 if cy < sy else 0
        if (sx + dx, sy + dy) in obstacles:
            dx = 0; dy = 0
        if dx != 0 or dy != 0:
            return [dx, dy]

